import{_ as i,l as E,o as e,c as n,v as t,p as l,x as r,d as p,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"层次风险平价 HRP","description":"","frontmatter":{"title":"层次风险平价 HRP","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hrp.md","filePath":"quant/hrp.md","lastUpdated":1789023840000}'),h={name:"quant/hrp.md"};function R(m,a,P,A,B,c){const o=E("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="层次风险平价-hrp" tabindex="-1">层次风险平价 HRP <a class="header-anchor" href="#层次风险平价-hrp" aria-label="Permalink to &quot;层次风险平价 HRP&quot;">​</a></h1><div class="epigraph"><p>先按相关把资产收成树，再在树上做逆方差分配，就不必去逆整张病态的协方差——层次结构本身就是正则。</p><footer>—— López de Prado, Building Diversified Portfolios that Outperform Out of Sample, Journal of Portfolio Management, 2016</footer></div><p><a href="/quant/dcc-portfolio">上一课</a>把 Engle 的 \\(H_t\\) 接入 ERC 或最小方差，对角与相关拆开用；未正则的 \\(H_t^{-1}\\) 仍会误差最大化。缺口是配置图：Markowitz 与 ERC 都在满 \\(\\Sigma\\) 上把每对资产当成完全图节点，\\(N/T\\) 小时噪声特征向量被当成可配置风险源，块状行业结构被忽略。本课钉层次风险平价：相关距离聚类、准对角化、沿树递归劈预算。不重讲 DCC 两步准似然。后课 ERC 默认 HRP 的分配是逆方差二分，不是嵌套再解一遍等贡献。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DCC 给出时变 \\(H_t\\)，配置若仍在完全图上求逆，噪声特征向照样进权重。样本协方差的逆放大最小特征值，最小方差权重稀疏且换手大；ERC 用满相关，高相关的重复名字会被当成两个贡献者而重复给预算，树状行业结构被忽略。需要一种规则：承认股票相关是块状的（行业、国家、因子），块内先压缩成一个风险单位，块间再分配，从而（1）避免逆满矩阵，（2）避免在同一簇里重复计数。层次聚类把「谁和谁是重复的」写成可审计的树，递归二分把「平价」定义在兄弟节点上，而不是定义在 \\(N\\) 个叶子的完全约束上。</p><p>HRP 的规范性主张是：样本外方差往往低于未收缩的最小方差与朴素 ERC，因为算法不能把质量堆到噪声方向上——那些方向通常不会形成稳定的簇。这不是定理保证的有效前沿，是一种对 \\(\\Sigma\\) 的图正则。若真相关不是层次的（所有两两相关几乎相等，或存在一个主导市场因子把树压扁），HRP 退化为接近逆波动的东西，增量消失。</p><h3 id="完全图假设在组合里过强" tabindex="-1">完全图假设在组合里过强 <a class="header-anchor" href="#完全图假设在组合里过强" aria-label="Permalink to &quot;完全图假设在组合里过强&quot;">​</a></h3><p>Markowitz 与 ERC 的一阶条件让每一对资产的协方差都直接进入每一个权重。一对估计得很吵的远距离相关（巴西股票与德国公用事业）也会微调两者的最优持仓。HRP 只让「树上的祖先」把预算传下来，远距离叶子之间没有直接的逆矩阵耦合。这是偏误：真的跨块对冲会被忽略；也是方差：噪声相关进不了权重。López de Prado 把这解释为机器学习式的正则——限制模型的比较集合，而不是再估一个更巧的 \\(\\Sigma^{-1}\\)。</p><p><span class="marginnote">HRP 不是「在 ERC 外面套一层聚类」的口头禅。若先聚类再在簇间做 ERC、簇内再 ERC，那是嵌套风险平价，仍要在每一层解等贡献，见 <a href="/quant/erc">ERC</a>。HRP 的分配规则是逆方差的递归二分，簇的方差用簇内逆方差组合来度量，数学对象不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三步，输入是相关矩阵 \\(C\\) 与方差向量（或完整 \\(\\Sigma\\)）。</p><p><strong>聚类。</strong> 距离 \\(d_{ij}=\\sqrt{(1-\\rho_{ij})/2}\\)（对相关的度量，满足同一性与对称；单链或 Ward 是否严格度量空间，实现里常直接用）。层次聚类得到树：叶子是资产，内部节点是簇。单链容易产生长条链，Ward 或平均链在股票上更常见；必须固定联动准则，否则树不可复现。</p><p><strong>准对角化。</strong> 按树的叶子序重排 \\(\\Sigma\\)，使大相关靠近对角线。这一步不改变任何特征值，只是为递归二分提供「左孩子 / 右孩子」的连续区间。序不唯一（每个子树可翻转），实现上要固定一种深度优先遍历，以免同一棵树对应两套权重。</p><p><strong>递归二分。</strong> 对当前簇，按树分成左右两块 \\(L,R\\)。先在块内用逆方差得到块的权重 \\(\\tilde w\\)，块方差 \\(V= \\tilde w^\\top \\Sigma_{\\mathrm{block}}\\tilde w\\)。再把本层预算按</p> \\[\\alpha=1-\\frac{V_L}{V_L+V_R} \\]<p>分给左块（右块 \\(1-\\alpha\\)），即方差大的一侧少拿预算。递归直到叶子。全市场权重是各层 \\(\\alpha\\) 的乘积。没有一次 \\(N\\times N\\) 的求逆；每次求逆只发生在块内对角（逆方差）或小块 \\(\\Sigma\\) 上。</p><h3 id="与逆波动、erc、最小方差的对照" tabindex="-1">与逆波动、ERC、最小方差的对照 <a class="header-anchor" href="#与逆波动、erc、最小方差的对照" aria-label="Permalink to &quot;与逆波动、ERC、最小方差的对照&quot;">​</a></h3><p>若树退化成「每个资产单独一类」，递归二分就是逆方差（对角 \\(\\Sigma\\)）。若相关全相等，聚类没有信息，HRP 接近逆波动。相关呈两块清晰结构时，HRP 先在块间按块方差分配，再在块内分配：高相关科技簇作为一个单位面对金融簇，不会让十只科技股各拿 \\(1/N\\) 的 ERC 预算。最小方差会在块内稀疏到一两只代表；HRP 默认在块内仍按逆方差铺开，更像「强制分散的因子风险平价」，不像 GMV 的角点解。</p><p>数值上 HRP 是 \\(O(N^2)\\) 的聚类加线性递归，稳定、无求解器失败。这是它在 \\(N\\) 数百时相对 ERC 牛顿法的工程优势。评价必须样本外：滚动估计 \\(C_t\\)，形成 HRP 权重，看下一期实现方差、换手、集中度。样本内把树拟合到同一段数据再报「HRP 波动更低」，没有内容。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是<strong>预算沿树向下、块内只看局部方差</strong>。两只高度相关的股票会很早并成一簇，此后它们只分享该簇分到的那一份风险预算，不能各自再向全局要一份——这正是 ERC 在重复资产上的缺陷。跨块的对冲需求若存在（例如多股票空指数期货），树若把期货放在很远的叶子，HRP 不会主动去做这个对冲，因为它从未在全局二次型里看到 \\(w^\\top\\Sigma w\\) 的交叉项可以被做空利用。多头单纯形上这通常可接受；多空组合上 HRP 的树要在有符号的相关或用因子残差上重建，否则空头腿会被当成又一个正波动叶子。</p><p>树的估计误差表现为「今天和明天簇的成员换人」。一只股票从科技划到消费，权重可以跳一截，即使 \\(\\Sigma\\) 的数值几乎没变。这是离散结构正则的通病：连续收缩（Ledoit–Wolf）权重连续，聚类权重分段常数。缓解：对 \\(C\\) 做平滑或收缩再聚类、对树做自助法共识（bootstrap aggregation of trees）、或把 HRP 权重与上期做 <a href="/quant/turnover-penalty">换手惩罚</a> 混合。</p><p><span class="marginnote">准对角化容易让人以为「矩阵已经接近对角、可以当对角处理」。重排不改变条件数。HRP 之所以不爆炸，是因为根本没有用那张满矩阵的逆，不是因为重排让它变好了。把准对角化后的 \\(\\Sigma\\) 拿去直接 Markowitz，病态原样在。</span></p><h3 id="距离与联动不是细节" tabindex="-1">距离与联动不是细节 <a class="header-anchor" href="#距离与联动不是细节" aria-label="Permalink to &quot;距离与联动不是细节&quot;">​</a></h3><p>\\(\\rho\\) 用多长窗口、是否先对市场因子残差再算相关，决定树在讲行业还是在讲 beta。全市场相关下，高 beta 股票会聚成一簇，HRP 变成某种 beta 分层；对市场中性残差聚类，树更接近行业 / 风格。全球股票再叠国家，树可能先按国家切开，<a href="/quant/industry-country-neutral">行业/国家中性</a> 的约束与 HRP 的树会打架：约束要求跨国家行业净零，树却可能把「日本银行」与「美国银行」放在不同国家簇里分开预算。应先声明树的输入是谁的相关：原始、对市场残差、还是对国家+行业残差。残差上的 HRP 才接近「特异风险平价」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 2016 年 JPM 文中的样本外胜出写成「HRP 优于均值方差」的普遍定理：对照若是未收缩的 GMV，任何正则都能赢。对照应包括 Ledoit–Wolf 最小方差、ERC、逆波动。不要在树未稳定时做日频 HRP 再平衡。不要对含衍生品、期权、非线性工具的账本直接用收益相关聚类。不要把 HRP 的叶子权重解释成「模型喜欢这只股票」——那只是它波动低且所在簇分到了预算。</p><p>HRP 不用 \\(\\mu\\)，不能表达观点；要观点应在树的某一层把 \\(\\alpha\\) 改成 BL 式倾斜，或把 HRP 当参考组合再跑 <a href="/quant/bl-views">Black-Litterman 观点</a>。卖空约束下树的距离若仍用相关，做空高相关资产这一 Markowitz 操作不存在。López de Prado 后续还有 HERC 等变体，把递归分配改成簇间 ERC；那是把本篇的逆方差二分换成等贡献二分，树还在，一阶条件变了，不要混名。</p><p><span class="marginnote">AFML 书里的实现细节（单链、递归代码）被大量复制。复制前应固定：相关的样本期、是否收缩、联动准则、子树遍历序、块方差用对角逆方差还是块 \\(\\Sigma\\)。这些不定，HRP 不是一个算法而是一个家族。</span></p>',29)),(e(),l(d,null,{default:r(()=>[s(o,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E7%9B%B8%E5%85%B3%E7%9F%A9%E9%98%B5%20C%22%5D%20--%3E%20DIST%5B%22%E8%B7%9D%E7%A6%BB%20d%20%3D%20sqrt((1-%CF%81)%2F2)%22%5D%0A%20%20DIST%20--%3E%20TREE%5B%22%E5%B1%82%E6%AC%A1%E8%81%9A%E7%B1%BB%E6%88%90%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20SER%5B%22%E5%87%86%E5%AF%B9%E8%A7%92%E5%8C%96%3A%20%E5%8F%B6%E5%AD%90%E5%BA%8F%E9%87%8D%E6%8E%92%20%CE%A3%22%5D%0A%20%20SER%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E4%BA%8C%E5%88%86%3A%20%E6%8C%89%E5%9D%97%E6%96%B9%E5%B7%AE%E5%8A%88%E9%A2%84%E7%AE%97%22%5D%0A%20%20REC%20--%3E%20W%5B%22HRP%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20MV%5B%22%E6%BB%A1%E7%9F%A9%E9%98%B5%20%CE%A3%5E%7B-1%7D%22%5D%20--%3E%20ILL%5B%22%E7%97%85%E6%80%81%20%2F%20%E8%AF%AF%E5%B7%AE%E6%94%BE%E5%A4%A7%22%5D%0A%20%20ERC%5B%22%E5%85%A8%E5%B1%80%20ERC%22%5D%20--%3E%20DUP%5B%22%E9%AB%98%E7%9B%B8%E5%85%B3%E5%90%8D%E5%AD%97%E9%87%8D%E5%A4%8D%E8%AE%A1%E6%95%B0%22%5D%0A%20%20W%20--%3E%20REG%5B%22%E6%A0%91%E7%BB%93%E6%9E%84%20%3D%20%E5%9B%BE%E6%AD%A3%E5%88%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HRP（López de Prado, 2016）用聚类树 + 准对角化 + 逆方差递归二分配置，避免逆满 \\(\\Sigma\\)，也不用 \\(\\mu\\)。</li><li>高相关资产先共享一簇的预算，修正 ERC 对重复名字的重复计数；代价是忽略远距离叶子之间的直接对冲。</li><li>树不稳定会造成权重跳跃，需平滑相关、共识聚类或换手惩罚。</li><li>对照应包括收缩最小方差与 ERC；击败未正则 GMV 不能当定理。</li><li>输入相关是否先残差化，决定树在讲 beta 还是讲行业，须与中性约束一致。</li><li>出处：López de Prado, <em>Journal of Portfolio Management</em>, 2016；算法展开见 <em>Advances in Financial Machine Learning</em>；相关距离与层次聚类为经典多元统计工具。</li></ul>',2))])}const _=i(h,[["render",R]]);export{C as __pageData,_ as default};
